-- Transactional cache generations; Redis is never authoritative for visibility.
CREATE TABLE ce_forum_cache_generation (name VARCHAR(80) PRIMARY KEY, generation VARCHAR(32) NOT NULL, scope VARCHAR(12) NOT NULL DEFAULT 'public');
